// Skyfire Squad character pipeline - step 1: generate source part sheets with Codex's built-in image_gen.
//
// Usage: node tools/character-pipeline/gen-sheets.mjs <armour suit tracksuit ninja hawaiian heads accessories weapons backs> [--version=v2]
// (always name the sheets: with no names every sheet is regenerated and the existing sources of that version are overwritten)
//
// Each sheet is generated by a separate `codex exec` run (ChatGPT login, built-in image_gen; no API key) with the
// owner's reference sheet attached, then copied to tools/character-pipeline/source/<name>-<version>.png. Every prompt,
// run log and output path is recorded in tools/character-pipeline/source/manifest.json.
import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const SRC = join(here, 'source');
const REF = join(here, 'references');
const CODEX = process.env.CODEX_BIN ?? 'C:/Users/vascu/RobloxPvP/tools/codex/bin/codex.exe';
mkdirSync(SRC, { recursive: true });

const args = process.argv.slice(2);
const version = (args.find((a) => a.startsWith('--version=')) ?? '--version=v2').split('=')[1];
const wanted = args.filter((a) => !a.startsWith('--'));

const COMMON = `Rules for the whole sheet:
- Strict orthographic SIDE VIEW facing RIGHT for every part. No perspective, no 3/4 view, no front view.
- Every part sits alone in its own grid cell, centred, with wide empty transparent space around it. Parts never touch or overlap.
- Limb parts are straight and perfectly VERTICAL, joint ends rounded so they can overlap the neighbouring part.
- Consistent scale, as if all parts were cut from ONE athletic character about 900 px tall and 4.5 heads tall
  (head about 200 px tall, upper arm and forearm about 200 px long, thigh about 240 px, shin with footwear about 260 px).
- Style: polished hand-drawn 2D action-game art matching the reference: clean confident dark-brown linework (not thick black outlines),
  crisp two- to three-tone cel shading, light from the top-left, subtle highlights, believable stylized anatomy.
- Fully transparent background. Absolutely NO joint markers, NO spheres or balls at joints, NO glow, NO drop shadows, NO halos,
  NO background colour, NO text, NO labels, NO weapons.
- Image size 1536x1024 (landscape).`;

const WEAPON_RULES = `Rules for the whole sheet:
- Strict orthographic SIDE VIEW, muzzle pointing RIGHT, every weapon perfectly HORIZONTAL. No perspective.
- Every weapon sits alone in its own grid cell, centred, with wide empty transparent space around it. Weapons never touch or overlap.
- Style: polished hand-drawn 2D action-game art matching the reference: clean confident dark linework (not thick black outlines),
  crisp two- to three-tone cel shading, light from the top-left, subtle highlights.
- Fully transparent background. NO hands, NO people, NO glow, NO muzzle flash, NO drop shadows, NO halos, NO text, NO labels.
- Image size 1536x1024 (landscape).`;

