function run(name) {
  return new Promise((resolve) => {
    const sheet = SHEETS[name];
    const out = join(SRC, `${name}-${version}.png`);
    const instr = `Use your built-in image_gen tool (not any CLI) to generate exactly ONE image as described below, then copy the generated PNG to
${out.replace(/\//g, '\\')}
and print the source path and the final path. Do not create or modify any other files.

${sheet.prompt}`;
    const log = join(SRC, `${name}-${version}.log`);
    const t0 = Date.now();
    const imgs = (sheet.refs ?? [sheet.ref]).flatMap((r) => ['-i', join(REF, r)]);
    const p = spawn(CODEX, ['exec', '--skip-git-repo-check', '-m', 'gpt-6.1-sol', ...imgs, '--', instr], { cwd: root, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let buf = '';
    p.stdout.on('data', (d) => (buf += d));
    p.stderr.on('data', (d) => (buf += d));
    p.on('close', (code) => {
      writeFileSync(log, buf);
      const ok = code === 0 && existsSync(out);
      console.log(`${name}: ${ok ? 'OK' : 'FAILED'} (${Math.round((Date.now() - t0) / 1000)} s) -> ${out}`);
      resolve({ name, version, ok, out, prompt: sheet.prompt, ref: sheet.refs ?? sheet.ref, seconds: Math.round((Date.now() - t0) / 1000), at: new Date().toISOString() });
    });
  });
}

if (!wanted.length) {
  console.error('Name the sheets to generate, e.g. node tools/character-pipeline/gen-sheets.mjs heads --version=v3');
  process.exit(1);
}
const names = wanted;
const results = await Promise.all(names.map(run));
const mf = join(SRC, 'manifest.json');
const manifest = existsSync(mf) ? JSON.parse(readFileSync(mf, 'utf8')) : { tool: 'codex exec + built-in image_gen (ChatGPT login)', sheets: [] };
manifest.sheets.push(...results);
writeFileSync(mf, JSON.stringify(manifest, null, 2));
